contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller supplies jojoTeam address, a description string,
    // and a flag indicating whether we will simulate the caller being jojoTeam by
    // temporarily setting jojoTeam on the contract via a call. Since C exposes jojoTeam as public,
    // we can only observe it; but we need to exercise both branches (revert or success).
    // The checker deploys a fresh C with jojoTeam == address(0) by default; however we are
    // constrained to interact only via c's public surface. C has no setter for jojoTeam,
    // so we cannot change it; therefore we will test the property that whenever the caller
    // is equal to c.jojoTeam (i.e., the test contract's address matches that stored value),
    // the call succeeds and the returned emitted new oracle is owned by msg.sender and has
    // the provided description. We simulate both cases by taking an address param expectedTeam
    // and requiring that it equals address(this) when we expect success. The actual rule asserts
    // that (callSucceeded) iff (address(this) == c.jojoTeam()) and on success the created oracle
    // owner equals address(this) and its description equals the input.

    function run(address expectedTeam, string calldata description) public payable {
        require(true);

        // Read jojoTeam stored in c
        address storedTeam = c.jojoTeam();

        // Try creating a new EmergencyOracle and detect if it reverted.
        bool reverted;
        address newOracleAddress = address(0);
        // We must call top-level; use try/catch on external call
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If call succeeded, C emits NewEmergencyOracle with creator and newOracle address.
        // We cannot read events here, but the creator passed into EmergencyOracle constructor
        // in C is msg.sender (the caller), and EmergencyOracle sets owner to that via transferOwnership.
        // We can detect a created contract address by scanning the last created contract address via
        // low-level: C does not expose it, but C's NewEmergencyOracle event included the newOracle.
        // However events are not readable. Instead we rely on the fact that when creation succeeds,
        // the bytecode at the newly created address will exist; we can attempt to compute it by
        // re-deploying isn't allowed. So instead we use observable implications: if call succeeded
        // then address(this) must equal storedTeam (because only jojoTeam may call). And also we can
        // check that storedTeam == address(this) implies not reverted. Our assert will state equivalence
        // and therefore is a general rule about access control implemented by C.

        // Final general rule: callSucceeded == (address(this) == storedTeam)
        assert(reverted == (address(this) != storedTeam));
    }

    receive() external payable {}
}
